using System;using System.IO;using System.Text;using System.Threading.Tasks;using System.Windows;
using Microsoft.Web.WebView2.Core;
public static class TerminalTests {
 public static async void RunTests(Application app,string folder){Directory.CreateDirectory(folder);foreach(var name in new[]{"terminal-error.txt","terminal-results.txt","terminal-review-results.txt","prompt-results.txt"}){string previous=Path.Combine(folder,name);if(File.Exists(previous))File.Delete(previous);}TerminalView remote=null,local=null;Window window=null;try{Theme.Apply("forest");var server=new Server{Name="SSH live diagnostic",Host="117.50.162.34",User="baiyang",Port=22,KeyPath=Path.Combine(Environment.GetEnvironmentVariable("USERPROFILE"),".ssh","id_rsa")};remote=new TerminalView(server,null);window=new Window{Title="AQServer Terminal diagnostic",Width=1080,Height=640,Left=-20000,Top=-20000,ShowActivated=false,ShowInTaskbar=false,Content=remote};window.Show();remote.RaiseEvent(new RoutedEventArgs(FrameworkElement.LoadedEvent));remote.RaiseEvent(new RoutedEventArgs(FrameworkElement.LoadedEvent));await Ready(remote);await PromptCheck(remote,folder,"remote");await ReviewChecks(remote,folder);remote.DiagnosticInput("printf '__AQ_WEBVIEW_中文__\\n'; stty size; printf '__AQ_SHELL_ENV__ user=%s conda=%s venv=%s\\n' \"$(id -un)\" \"$CONDA_DEFAULT_ENV\" \"$VIRTUAL_ENV\"\r");await Task.Delay(2200);string first=await Buffer(remote);Check(first.Contains("__AQ_WEBVIEW_中文__")&&first.Contains("user=baiyang"),"SSH and UTF8 output in xterm");Check(remote.State.Contains("baiyang@")&&remote.State.Contains("bash"),"real shell status hook");Check(!string.IsNullOrEmpty(remote.WorkingDirectory)&&remote.ShellName=="bash"&&!string.IsNullOrEmpty(remote.UserHost),"separate real shell status fields");window.Width=960;window.Height=560;await Task.Delay(600);remote.DiagnosticInput("stty size\r");await Task.Delay(600);remote.DiagnosticInput("vim -Nu NONE -n -i NONE\r");await Task.Delay(1000);Check((await remote.DiagnosticWeb.ExecuteScriptAsync("term.buffer.active.type")).Contains("alternate"),"vim alternate screen");remote.DiagnosticInput("\x1b:q!\r");await Task.Delay(600);remote.DiagnosticInput("top\r");await Task.Delay(1200);Check((await Buffer(remote)).Contains("load average"),"interactive top output");remote.DiagnosticInput("q");await Task.Delay(600);remote.DiagnosticInput("sleep 30\r");await Task.Delay(400);remote.DiagnosticInput("\x03");await Task.Delay(400);remote.DiagnosticInput("printf '__AQ_AFTER_CTRL_C__\\n'\r");await Task.Delay(900);string result=await Buffer(remote);Check(result.Contains("__AQ_AFTER_CTRL_C__"),"interactive Ctrl+C followed by working prompt");remote.DiagnosticInput("clear; printf 'AQServer · interactive SSH · UTF-8 中文终端\\n\\n'; printf 'user=%s  host=%s\\ncwd=%s\\nconda=%s  venv=%s\\n\\n' \"$(id -un)\" \"$(hostname)\" \"$PWD\" \"$CONDA_DEFAULT_ENV\" \"$VIRTUAL_ENV\"\r");await Task.Delay(700);using(var stream=File.Create(Path.Combine(folder,"terminal-remote-webview.png")))await remote.DiagnosticWeb.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);File.WriteAllText(Path.Combine(folder,"terminal-remote-buffer.json"),result,Encoding.UTF8);File.WriteAllText(Path.Combine(folder,"terminal-results.txt"),"SSH_UTF8_XTERM=True\nREAL_USER_CWD_SHELL_ENV_STATUS="+remote.State+"\nVIM_TOP_INTERACTIVE=True\nCTRL_C_RESUMES_SHELL=True\nCAPTURE=terminal-remote-webview.png\nNOTE=IME physical composition and clipboard require human review; no credentials persisted.\n",Encoding.UTF8);
 remote.DiagnosticInput("conda deactivate\r");await Task.Delay(700);Check(!remote.State.StartsWith("(base)"),"environment deactivation is reflected");remote.DiagnosticInput("for i in {1..12000}; do printf 'aq-pressure-%s\\n' \\\"$i\\\"; done; printf '__AQ_PRESSURE_COMPLETE__\\n'\r".Replace("\\\"","\""));await Task.Delay(2200);Check((await Buffer(remote)).Contains("__AQ_PRESSURE_COMPLETE__"),"bounded output completes");int lines=int.Parse(await remote.DiagnosticWeb.ExecuteScriptAsync("term.buffer.active.length"));Check(lines<=5300,"scrollback bounded");File.AppendAllText(Path.Combine(folder,"terminal-results.txt"),"CONDA_DEACTIVATE_UPDATES_STATUS=True\nOUTPUT_PRESSURE_LINES=12000\nSCROLLBACK_BOUNDED="+lines+"\n");local=new TerminalView(new Server{IsLocal=true,Name="本机"},null);window.Content=local;await Ready(local);await PromptCheck(local,folder,"local");local.DiagnosticInput("Write-Output '__AQ_LOCAL_中文__'\r");string localOutput="";for(int attempt=0;attempt<60;attempt++){await Task.Delay(250);localOutput=await Buffer(local);if(localOutput.Contains("__AQ_LOCAL_中文__"))break;}File.WriteAllText(Path.Combine(folder,"terminal-local-buffer.json"),localOutput,Encoding.UTF8);Check(localOutput.Contains("__AQ_LOCAL_中文__"),"second independent local shell");File.AppendAllText(Path.Combine(folder,"terminal-results.txt"),"LOCAL_POWERSHELL_UTF8=True\nTWO_OWNED_SESSIONS_CONCURRENT=True\n");local.Dispose();remote.Dispose();window.Close();app.Shutdown(0);
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"terminal-error.txt"),ex.ToString());if(local!=null)local.Dispose();if(remote!=null)remote.Dispose();if(window!=null)window.Close();app.Shutdown(1);}}
 static async Task PromptCheck(TerminalView view,string folder,string kind){
 string js="JSON.stringify({x:term.buffer.active.cursorX,y:term.buffer.active.cursorY,line:term.buffer.active.getLine(term.buffer.active.baseY+term.buffer.active.cursorY).translateToString(true)})";
 for(int i=0;i<60;i++){string text=await view.DiagnosticWeb.ExecuteScriptAsync(js);if(!string.IsNullOrEmpty(view.WorkingDirectory)&&text.Contains("@")&&text.Contains(kind=="local"?">":"$"))break;await Task.Delay(250);}
 string before=await view.DiagnosticWeb.ExecuteScriptAsync(js);File.WriteAllText(Path.Combine(folder,"prompt-"+kind+"-before.json"),before);File.WriteAllText(Path.Combine(folder,"prompt-"+kind+"-raw.txt"),view.DiagnosticRawOutput);File.WriteAllText(Path.Combine(folder,"prompt-"+kind+"-clean.txt"),view.DiagnosticCleanOutput);
 string cursor=await view.DiagnosticWeb.ExecuteScriptAsync("(()=>{const b=term.buffer.active,end=b.baseY+b.cursorY;let start=end;while(start>0&&b.getLine(start).isWrapped)start--;let text='';for(let y=start;y<=end;y++)text+=b.getLine(y).translateToString(false);const offset=(end-start)*term.cols+b.cursorX,prefix=text.slice(0,offset);window.__aqPromptCheck={start,prefix};return JSON.stringify({ok:offset>0&&prefix.includes('@')&&/[>$] $/.test(prefix),x:b.cursorX,line:text.trimEnd()});})()");
 Check(cursor.Contains("true"),kind+" cursor must follow actual prompt before typing: "+cursor);
 view.DiagnosticInput("echo __AQ_CURSOR_CHECK__");await Task.Delay(600);
 string after=await view.DiagnosticWeb.ExecuteScriptAsync(js);File.WriteAllText(Path.Combine(folder,"prompt-"+kind+"-typed.json"),after);
 string verify="";for(int attempt=0;attempt<60;attempt++){verify=await view.DiagnosticWeb.ExecuteScriptAsync("(()=>{const b=term.buffer.active,end=b.baseY+b.cursorY,p=window.__aqPromptCheck;let line='';for(let y=p.start;y<=end;y++)line+=b.getLine(y).translateToString(y==end);return JSON.stringify({ok:line.startsWith(p.prefix+'echo __AQ_CURSOR_CHECK__'),line,cursorX:b.cursorX});})()");if(verify.Contains("true"))break;await Task.Delay(150);}
 Check(verify.Contains("true"),kind+" command must follow actual prompt: "+verify);view.DiagnosticInput("\x15");await Task.Delay(200);File.AppendAllText(Path.Combine(folder,"prompt-results.txt"),kind+"_INPUT_AFTER_PROMPT=PASS\n");
 }
 static async Task ReviewChecks(TerminalView remote,string folder){
 Check(TerminalCommands.ShellScript("PS1='test> '\r\nprintf ready\r\n")=="PS1='test> '\nprintf ready\n","Windows shell script line endings cannot enter PS1");
 Check(remote.DiagnosticInitializations==1&&remote.DiagnosticSessionsStarted==1,"Loaded reentry creates one initialization/session");
 await remote.DiagnosticWeb.ExecuteScriptAsync("send('ready','80,24');send('ready','80,24')");await Task.Delay(150);Check(remote.DiagnosticSessionsStarted==1,"duplicate ready does not create a second process");
 remote.DiagnosticConfirmPaste=delegate(string value){return false;};int count=remote.DiagnosticPasteRequests;
 await remote.DiagnosticWeb.ExecuteScriptAsync("(()=>{const d=new DataTransfer();d.setData('text/plain',\"printf '__AQ_DENIED_PASTE__'\\nprintf '__AQ_DENIED_SECOND__'\\n\");document.querySelector('.xterm-helper-textarea').dispatchEvent(new ClipboardEvent('paste',{bubbles:true,cancelable:true,clipboardData:d}));})()");await Task.Delay(250);
 Check(remote.DiagnosticPasteRequests==count+1&&remote.DiagnosticLastPaste.Contains("__AQ_DENIED_SECOND__"),"DOM native paste routes through host confirmation");Check(!(await Buffer(remote)).Contains("__AQ_DENIED_PASTE__"),"denied multiline paste never reaches shell");
 remote.DiagnosticReadClipboard=delegate{return "printf '__AQ_KEY_PASTE__'";};
 foreach(string code in new[]{"KeyV","Insert"}){count=remote.DiagnosticPasteRequests;string keyboard=code=="KeyV"?"{key:'v',code:'KeyV',ctrlKey:true,bubbles:true,cancelable:true}":"{key:'Insert',code:'Insert',shiftKey:true,bubbles:true,cancelable:true}";await remote.DiagnosticWeb.ExecuteScriptAsync("document.querySelector('.xterm-helper-textarea').dispatchEvent(new KeyboardEvent('keydown',"+keyboard+"))");await Task.Delay(200);Check(remote.DiagnosticPasteRequests==count+1,"keyboard paste "+code+" uses host path");remote.DiagnosticInput("\x15");await Task.Delay(100);}
 remote.DiagnosticReadClipboard=null;remote.DiagnosticConfirmPaste=null;
 string alias=TerminalCommands.Build(new Server{Host="aq-config-alias",User="",Port=22},null);Check(!alias.Contains(" -l "),"empty username defers to SSH config");
 File.WriteAllText(Path.Combine(folder,"terminal-review-results.txt"),"SHELL_SOURCE_LINE_ENDINGS_NORMALIZED=True\nINITIALIZE_REENTRY_GUARD=True\nDUPLICATE_READY_ONE_SESSION=True\nDOM_PASTE_HOST_CONFIRMATION=True\nDENIED_MULTILINE_NEVER_SENT=True\nCTRL_V_HOST_PATH=True\nSHIFT_INSERT_HOST_PATH=True\nEMPTY_SSH_USER_CONFIG_FALLBACK=True\n");
 }
 static async Task Ready(TerminalView view){for(int i=0;i<100&&!view.DiagnosticReady;i++)await Task.Delay(150);Check(view.DiagnosticReady,"WebView2 + xterm ready: "+view.State);await Task.Delay(2500);}
 static Task<string> Buffer(TerminalView view){return view.DiagnosticWeb.ExecuteScriptAsync("(()=>{let b=term.buffer.active,s='';for(let i=0;i<b.length;i++)s+=b.getLine(i).translateToString(true)+'\\n';return s;})()");}
 static void Check(bool value,string label){if(!value)throw new Exception(label);}
}
